import java.util.*;

public class acm1 {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int b = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        PriorityQueue<Integer> cuts = new PriorityQueue<Integer>();
        int even = 0, odd = 0;

        for (int i = 0; i < n; i++) {
            if (i != 0 && even == odd) {
                cuts.add(Math.abs(arr[i] - arr[i - 1]));
            }
            if (arr[i] % 2 == 0) {
                even++;
            } else {
                odd++;
            }
        }

        int count = 0;
        while (!cuts.isEmpty()) {
            int cost = cuts.poll();
            if (cost <= b) {
                count++;
                b -= cost;
            } else {
                break;
            }
        }

        System.out.println(count);
    }

}
